#include <vector>

class Solution {
public:
    int numTeams(std::vector<int>& rating) {
        int n = rating.size(), teams = 0;
        for (int j = 0; j < n; ++j) {
            int leftLess = 0, rightLess = 0;
            for (int i = 0; i < j; ++i) if (rating[i] < rating[j]) leftLess++;
            for (int k = j + 1; k < n; ++k) if (rating[k] < rating[j]) rightLess++;
            int leftGreater = j - leftLess;
            int rightGreater = (n - 1 - j) - rightLess;
            teams += leftLess * rightGreater + leftGreater * rightLess;
        }
        return teams;
    }
};

